<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$id=max(1,(int)($_GET['id']??$uid));$m=dn_member_by_id($db,$id);if(!$m){nxt_status_page(404,'Tamer not found','This tamer profile is no longer available.');}$isBot=(bool)dn_row($db,'SELECT owner_id FROM nxt_bots WHERE owner_id=?',[$id]);$stats=dn_member_public_stats($db,$id);$party=dn_party_rows($db,$id);$friend=$id!==$uid?dn_friend_status($db,$uid,$id):null;pv_page_start((string)$m['username'],'community.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('community.php');?><main class="pv-main-column"><section class="pv-page"><section class="pv-card" style="padding:24px"><div class="pv-trainer-profile-grid"><div class="pv-trainer-avatar" style="max-width:150px"><img src="<?=pv_h(nxt_skin_url((int)$m['tamer']))?>" alt=""></div><div><span class="pv-eyebrow"><?= $isBot?'AI RIVAL PROFILE':'PLAYER PROFILE' ?> // <?=($stats['online']?'ONLINE':'OFFLINE')?></span><h1><?=pv_h((string)$m['username'])?></h1><p class="pv-subtle"><?=pv_h((string)($m['bio']?:'No profile transmission has been set.'))?></p><div class="dn-stat-strip"><div><span>Owned</span><strong><?=(int)$stats['digimon']?></strong></div><div><span>Seen</span><strong><?=(int)$stats['seen']?></strong></div><div><span>Wins</span><strong><?=(int)$m['wins']?></strong></div><div><span>Bits</span><strong><?=number_format((int)$m['money'])?></strong></div></div><p><?=($stats['clan']!==''?'Clan: '.pv_h($stats['clan']).' · ':'')?>Registered <?=date('Y-m-d',(int)$m['registered'])?></p><div class="pv-actions"><?php if($id===$uid):?><a class="pv-button" href="<?=pv_h(pv_url('your_account.php'))?>">Edit Profile</a><?php elseif($isBot):?><a class="pv-button" href="<?=pv_h(pv_url('tamer_rivals.php'))?>">Rival records</a><?php else:?><a class="pv-button" href="<?=pv_h(pv_url('messages.php?to='.rawurlencode((string)$m['username'])))?>">Message</a><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('community.php'))?>"><?=($friend&&$friend['status']==='accepted')?'Connected':'Community'?></a><?php endif;?></div></div></div></section><section class="pv-card" style="padding:20px;margin-top:14px"><span class="pv-eyebrow">PUBLIC ACTIVE PARTY</span><h2>Linked Digimon</h2><?php if($party):?><div class="dn-digimon-grid"><?php foreach($party as $d)echo dn_digimon_card($d,false);?></div><?php else:?><div class="pv-empty">No public party data.</div><?php endif;?></section></section></main></div><?php pv_page_end(); ?>
